import {BY_ID,boundaryWalls,portSegment,segmentDistance} from './architecture.js';import {toLocal,toWorld} from './pose.js';import {doorLeaf,doorSweepDistance} from './doors.js';import {capsuleSurface} from './stage11-layout.js';
export function capsuleOwner(s,x,z,y){const p=s.positions.CP1;if(!p)return null;const q=toLocal(p,{x,y,z}),h=capsuleSurface(q.x,q.z,q.y);return h!==null&&Math.abs(h-q.y)<.311?'CP1':null;}
export function movementHeight(s,x,z,y){const p=s.positions.CP1;if(!p)return y;const q=toLocal(p,{x,y,z}),h=capsuleSurface(q.x,q.z,q.y);return h!==null&&Math.abs(h-q.y)<=.181?p.y+h:y;}
export function capsuleClear(s,x,z,y,radius){const p=s.positions.CP1,q=toLocal(p,{x,y,z}),b=BY_ID.CP1;if(!b)return true;
 const lines=[...boundaryWalls(b).map(l=>({...l,height:5.6})),...b.walls,...b.doors.map(d=>({...doorLeaf(d,s.doors[d.id]?1:s.experience.doorProgress[d.id]??0),floor:d.floor??0,height:2.05}))];
 if(q.y>2.8)lines.push(...[{a:[.06,0],b:[.06,8]},{a:[7.94,0],b:[7.94,8]},{a:[0,.06],b:[8,.06]},{a:[0,7.94],b:[8,7.94]},{a:[5.4,6.6],b:[7.8,6.6]}].map(l=>({...l,floor:3,height:2.6})));
 if(q.z>1.35&&q.z<6.45&&q.y>=capsuleSurface(6.5,q.z,q.y)-.16)for(const xx of[5.4,7.8])if(Math.abs(q.x-xx)<radius+.06)return false;
 for(const l of lines){const f=l.floor??0;if(q.y<f-.01||q.y>=f+(l.height??2.84)-.1)continue;if(segmentDistance(q.x,q.z,l.a,l.b)<radius+.06-1e-7)return false;}
 for(const a of b.ports){if(q.y>2)continue;const state=s.livePorts.find(v=>v.key===b.id+':'+a.id);for(const m of state?.masked??[{a:a.a,b:a.b}]){const l=portSegment(b,{...a,...m});if(segmentDistance(q.x,q.z,l.a,l.b)<radius+.06)return false;}}
 for(const r of b.furniture){if(Math.abs(q.y-(r.floor??0))>.3)continue;if(Math.hypot(Math.max(r.x-q.x,0,q.x-r.x-r.w),Math.max(r.z-q.z,0,q.z-r.z-r.d))<radius+.01)return false;}return true;
}
export function insideLoadedMap(s,x,z,y){if(!s.loadedInterior){const p=s.positions.LB1,q=p?toLocal(p,{x,y,z}):null;return !q||Math.abs(q.y)>.02||q.x<=1.15||q.x>16||q.z<0||q.z>8;}const q=toLocal(s.positions.LB1,{x,y,z});return q.x>=1.61&&q.x<=15.6&&q.z>=.4&&q.z<=7.6;}
export function safeInteriorStay(s){if(s.owner==='CP1'){const q=toLocal(s.positions.CP1,s.player);return q.x>=.46&&q.x<=7.54&&q.z>=.46&&q.z<=7.54&&s.isFree(s.player.x,s.player.z,s.player.y);}return!!s.loadedInterior&&s.owner===s.loadedInterior.body&&insideLoadedMap(s,s.player.x,s.player.z,s.player.y);}
export function specialDoor(s,b,d){if(!d.capsuleView&&!d.entrance)return null;if(s.mode!=='idle'||s.owner!==b.id||s.buildingTransition)return false;
 if(d.capsuleView){if(Math.abs(s.player.y-s.positions[b.id].y-(d.floor??0))>.05)return false;const e=s.experience;e.visitBody=b.id;e.lastVisitDoor=d.id;e.visit={body:b.id,npc:'capsule-test',testModel:true,door:d.id,player:{...s.player},local:toLocal(s.positions[b.id],s.player)};e.focus={body:b.id,camera:d.capsuleView.camera,look:d.capsuleView.look};e.blend=1;e.doorTargets[d.id]=false;e.doorProgress[d.id]=0;s.doors[d.id]=false;e.transitionTo('enter');s.message=d.label+'：既存の住人モデルを再利用した構図試験';return true;}
 return s.loadedInterior?exitLab(s):enterLab(s);
}
function beginLabTransition(s,kind){if(s.buildingTransition)return false;const q=toLocal(s.positions.LB1,s.player);for(const d of BY_ID.LB1.doors.filter(d=>d.entrance))if(!s.loadedInterior&&doorSweepDistance(d,q,0,1)<.4){s.message='二枚扉の可動範囲から少し離れて操作してください。';return false;}
 s.buildingTransition={kind,elapsed:0,duration:.5,switched:false};s.experience.transitionTo('lab-'+kind);s.experience.transition.duration=.5;for(const d of BY_ID.LB1.doors.filter(d=>d.entrance))s.experience.doorTargets[d.id]=true;return true;
}
export function enterLab(s){return beginLabTransition(s,'enter');}
export function labExitNearby(s){if(!s.loadedInterior)return false;const q=toLocal(s.positions.LB1,s.player);return segmentDistance(q.x,q.z,[1.2,5.5],[1.2,7.5])<=2.4;}
export function exitLab(s){if(!s.loadedInterior)return false;if(s.mode!=='idle'||s.anyLiftActive){s.message='搬送完了まで研究所から退出できません。';return false;}if(!s.livePorts.some(p=>p.body==='LB1'&&p.status==='pass')){s.message='この周期は研究所入口が未接続です。再接続搬送でCへ進めてください。';return false;}const q=toLocal(s.positions.LB1,s.player);if(segmentDistance(q.x,q.z,[1.2,5.5],[1.2,7.5])>2.4){s.message='退出するには入口の二枚扉へ戻ってください。';return false;}return beginLabTransition(s,'exit');}
export function tickBuildingTransition(s,dt){const t=s.buildingTransition;if(!t)return;t.elapsed+=dt;if(t.elapsed>=t.duration/2&&!t.switched){t.switched=true;const enter=t.kind==='enter';s.loadedInterior=enter?{body:'LB1'}:null;s.player={...s.player,...toWorld(s.positions.LB1,{x:enter?2.2:.65,y:0,z:6.5}),yaw:(enter?Math.PI/2:-Math.PI/2)-(s.positions.LB1.angle??0)*Math.PI/180};for(const d of BY_ID.LB1.doors.filter(d=>d.entrance)){s.doors[d.id]=false;s.experience.doorTargets[d.id]=false;s.experience.doorProgress[d.id]=0;}s.invalidate();}if(t.elapsed>=t.duration){s.buildingTransition=null;s.message=s.loadedInterior?'研究所内部：WASDで探索。二枚扉付近でEを押して退出。':'現在の研究所前室へ退出しました。';}}
